public class Main {
    public static void main(String[] args) {
        Greeter g = new LoudGreeter();
        System.out.println(g.greet());
    }
}

class Greeter {
    String greet() {
        return "Hello";
    }
}

class LoudGreeter extends Greeter {
    @Override
    String greet() {
        return super.greet().toUpperCase() + "!";
    }
}
